-- Copper & Kings (copperandkings.com) via catalog.sources.bourbon.copper_kings; applied 2026-10-11. 1 listed-not-confirmed correction (finish), 1 addition.
update cellar.makers set website = 'https://copperandkings.com', country = coalesce(country, 'US') where id = '01fc9444-bfb7-4bd7-aafc-033ec251ff0d' and website is null;
update cellar.products set finish = 'Brandy Barrels', producer = coalesce(producer, 'Copper & Kings'), producer_id = coalesce(producer_id, '01fc9444-bfb7-4bd7-aafc-033ec251ff0d'::uuid), source_url = 'https://copperandkings.com/product/kentucky-straight-bourbon/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'a5d2d16d-7a7c-45ce-ab4e-4ab724e091e5' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('a5d2d16d-7a7c-45ce-ab4e-4ab724e091e5');
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Copper & Kings King's Proof","rar":"shelf","f":"Copper & Kings","x":"King's Proof","p":114.8,"ay":null,"al":"5–15 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":"Brandy Barrels","msrp":null,"core":true,"al2":["Copper & Kings King's Proof Bourbon"],"img":"https://copperandkings.com/wp-content/uploads/2026/08/Kings-Proof.png","u":"https://copperandkings.com/product/kings-proof-bourbon/","pr":"Copper & Kings","mk":"01fc9444-bfb7-4bd7-aafc-033ec251ff0d"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
